(()=>{
 'use strict';
 const root=document.documentElement,hero=document.querySelector('.motion-hero'),scene=document.querySelector('.cloud-atelier'),video=document.querySelector('#cloud-film'),panel=scene.querySelector('.cloud-window'),buttons=[...scene.querySelectorAll('[data-cloud-stage]')],reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const stages=[['일상에서 발견','나의 작은 질문이,<br>변화의 시작이 됩니다.','함께 듣고, 문제를 정리하고.<br>무엇을 바꾸고 싶은지부터 발견합니다.'],['AI와 함께 제작','머릿속의 생각을,<br>작동하는 해결책으로.','문제를 정의하고 MD 문서로 설계한 뒤,<br>AI와 만들고 직접 써 보며 고칩니다.'],['함께 시연하는 순간','막막했던 두려움이,<br>해냈다는 성취감으로.','내 생각이 눈앞에서 움직이던 순간.<br>우리의 일상을 바꿀 자신감이 생겼습니다.']];
 let current=0,visible=true,timer=0,manual=false,running=false;
 function show(index){current=index;const s=stages[index];scene.querySelector('#cloud-stage-label').textContent=`0${index+1} · ${s[0]}`;scene.querySelector('#cloud-stage-title').innerHTML=s[1];scene.querySelector('#cloud-stage-copy').innerHTML=s[2];scene.querySelector('#cloud-chapter').textContent=`0${index+1} / 03`;buttons.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));scene.querySelector('.cloud-progress span').style.transform=`translateX(${index*100}%)`;scene.classList.remove('cloud-changing');void panel.offsetWidth;scene.classList.add('cloud-changing');}
 function cycle(){clearTimeout(timer);if(running&&!manual)timer=setTimeout(()=>{show((current+1)%3);cycle();},6800);}
 function state(){const active=root.dataset.mode==='cloud';if(active)hero.setAttribute('aria-labelledby','cloud-title');const next=active&&visible&&!document.hidden&&!reduced.matches&&!document.body.classList.contains('motion-paused');scene.classList.toggle('cloud-sleep',!next);if(next){if(!video.getAttribute('src'))video.src='assets/cloud-film.mp4';video.play().catch(()=>{});}else video.pause();if(next!==running){running=next;cycle();}}
 buttons.forEach((button,i)=>button.addEventListener('click',()=>{manual=true;clearTimeout(timer);show(i);}));
 panel.addEventListener('pointermove',e=>{if(!running||!matchMedia('(hover:hover) and (pointer:fine)').matches)return;const r=panel.getBoundingClientRect();panel.style.setProperty('--cloud-ry',`${(e.clientX-r.left-r.width/2)/r.width*7}deg`);panel.style.setProperty('--cloud-rx',`${-(e.clientY-r.top-r.height/2)/r.height*5}deg`);});panel.addEventListener('pointerleave',()=>{panel.style.setProperty('--cloud-rx','0deg');panel.style.setProperty('--cloud-ry','0deg');});
 video.addEventListener('playing',()=>scene.classList.add('cloud-video-ready'));video.addEventListener('error',()=>scene.classList.remove('cloud-video-ready'));
 new IntersectionObserver(e=>{visible=e[0].isIntersecting;state();}).observe(hero);new MutationObserver(state).observe(document.body,{attributes:true,attributeFilter:['class']});document.addEventListener('design-mode-change',state);document.addEventListener('visibilitychange',state);reduced.addEventListener('change',state);state();
})();
